}

Method.Source:
/// <summary>
/// DebuC 22.09.23
/// </summary>
static void checkPartyId()
{
    NDXKumBonCust           nDXKumBonCust1, nDXKumBonCust2;

    Query                   q1, q2;
    QueryRun                qr1, qr2;
    QueryBuildDataSource    qbds1, qbds2;
    ;
    q1 = new Query();
    qbds1 = q1.addDataSource(tablenum(NDXKumBonCust));
    qbds1.orderMode(OrderMode::GroupBy);
    qbds1.addGroupByField(fieldnum(NDXKumBonCust, CompanyId));
    qr1 = new QueryRun(q1);
    while (qr1.next())
    {
        nDXKumBonCust1 = qr1.get(tablenum(NDXKumBonCust));
        changecompany(nDXKumBonCust1.CompanyId)
        {
            q2 = new Query();
            qbds2 = q2.addDataSource(tablenum(NDXKumBonCust));
            qbds2.update(true);
            qbds2.addRange(fieldnum(NDXKumBonCust, CompanyId)).value(nDXKumBonCust1.CompanyId);
            qbds2.addRange(fieldnum(NDXKumBonCust, Party)).value(SysQuery::valueEmptyString());
            qr2 = new QueryRun(q2);
            while (qr2.next())
            {
                ttsbegin;
                nDXKumBonCust2 = qr2.get(tablenum(NDXKumBonCust));
                nDXKumBonCust2.Party = CustTable::find(nDXKumBonCust2.CustAccount).Party;
                nDXKumBonCust2.update();
                ttscommit;
            }
        }
    }
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_FirmenNr">NDXCompanys</param>
/// <param name = "l_CustAccount">CustAccount</param>
/// <param name = "_Jahr">NDXYear</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXKumBonCust</returns>
static NDXKumBonCust find(NDXCompanys       _FirmenNr,
                       CustAccount     l_CustAccount,
                       NDXYear        _Jahr,
                       boolean _forUpdate = false)
{
    NDXKumBonCust umsatz;
    ;
    umsatz.selectForUpdate(_forUpdate);

    if (_FirmenNr && l_CustAccount && _Jahr)
    {
        select umsatz
            where   umsatz.Company        == _FirmenNr            &&
                    umsatz.CustAccount  == l_CustAccount        &&
                    umsatz.Year         == _Jahr;
    }

    return umsatz;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "monat">NDXMonthBE</param>
void initBonMonat(NDXMonthBE monat)
{
    ;
    switch (monat)
    {
        case NDXMonthBE::January   :   
            this.Bonus01 = 0; 
            break;
        case NDXMonthBE::February  :   
            this.Bonus02 = 0; 
            break;
        case NDXMonthBE::March     :   
            this.Bonus03 = 0; 
            break;
        case NDXMonthBE::April     :   
            this.Bonus04 = 0; 
            break;
        case NDXMonthBE::May       :   
            this.Bonus05 = 0; 
            break;
        case NDXMonthBE::June      :   
            this.Bonus06 = 0; 
            break;
        case NDXMonthBE::July      :   
            this.Bonus07 = 0; 
            break;
        case NDXMonthBE::August    :   
            this.Bonus08 = 0; 
            break;
        case NDXMonthBE::September :   
            this.Bonus09 = 0; 
            break;
        case NDXMonthBE::October   :   
            this.Bonus10 = 0; 
            break;
        case NDXMonthBE::November  :   
            this.Bonus11 = 0; 
            break;
        case NDXMonthBE::December  :   
            this.Bonus12 = 0; 
            break;
    }
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_NDX_KumBonCust">NDXKumBonCust</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXKumBonCust</returns>
client server static public NDXKumBonCust findOrCreate(NDXKumBonCust _NDX_KumBonCust, boolean _forUpdate = false)
{
    NDXKumBonCust      nDX_KumBonCust;
    ;
    nDX_KumBonCust = NDXKumBonCust::findRecord(_NDX_KumBonCust, _forUpdate);
    if (!nDX_KumBonCust.RecId)
    {
        nDX_KumBonCust = NDXKumBonCust::create(_NDX_KumBonCust, _forUpdate);
    }

    return nDX_KumBonCust;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_NDX_KumBonCust">NDXKumBonCust</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXKumBonCust</returns>
client server static public NDXKumBonCust findRecord(NDXKumBonCust _NDX_KumBonCust, boolean _forUpdate = false)
{
    NDXKumBonCust   nDX_KumBonCust;
    ;
    if (_forUpdate)
    {
        nDX_KumBonCust.selectForUpdate(_forUpdate);
    }

    if (_NDX_KumBonCust.CompanyId && _NDX_KumBonCust.CustAccount && _NDX_KumBonCust.Year)
    {
        select firstOnly    nDX_KumBonCust
            where           nDX_KumBonCust.CompanyId    == _NDX_KumBonCust.CompanyId        &&
                            nDX_KumBonCust.CustAccount  == _NDX_KumBonCust.CustAccount      &&
                            nDX_KumBonCust.Year         == _NDX_KumBonCust.Year;
    }
    else if (_NDX_KumBonCust.KdNr && _NDX_KumBonCust.Company && _NDX_KumBonCust.Year)
    {
        select firstOnly    nDX_KumBonCust
            where           nDX_KumBonCust.KdNr         == _NDX_KumBonCust.KdNr             &&
                            nDX_KumBonCust.Company      == _NDX_KumBonCust.Company            &&
                            nDX_KumBonCust.Year         == _NDX_KumBonCust.Year;
    }

    return nDX_KumBonCust;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_NDX_KumBonCust">NDXKumBonCust</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXKumBonCust</returns>
server static public NDXKumBonCust create(NDXKumBonCust _NDX_KumBonCust, boolean _forUpdate = false)
{
    NDXKumBonCust  nDX_KumBonCust;
    ;
    try
    {
        ttsbegin;
        nDX_KumBonCust.selectForUpdate(_forUpdate);
        nDX_KumBonCust.CompanyId   = _NDX_KumBonCust.CompanyId;
        nDX_KumBonCust.CustAccount = _NDX_KumBonCust.CustAccount;
        nDX_KumBonCust.Party       = _NDX_KumBonCust.Party;                   // 1.1: NDX/PAFFH/NDX_TASK1235003633/20.02.2014
        nDX_KumBonCust.KdNr        = _NDX_KumBonCust.KdNr;
        nDX_KumBonCust.Company     = _NDX_KumBonCust.Company;
        nDX_KumBonCust.Year        = _NDX_KumBonCust.Year;
        nDX_KumBonCust.insert();
        ttscommit;
    }
    catch
    {
        throw Error(strfmt("@NDX:NDXKumUmsBonCustNotCreated",  _NDX_KumBonCust.KdNr));     // Datensatz in NDX_KumBonCust [%1] kann nicht angelegt werden
    }

    return nDX_KumBonCust;
}

